//! Vertex-only rounds, distinct from rounding the incident edges.

use ogeom_algo::Built;
use ogeom_core::{OgeomResult, Tolerances};
use ogeom_topo::{Model, Shape, ShapeType};

use super::vertex_read::{Corner, OneBall, corner_at};

/// Round a solid's convex vertex with a ball of `radius`.
///
/// Only the corner is rounded: each incident edge stays sharp beyond its
/// plane through the ball's centre square to that edge. The spherical
/// corner and those planar caps are generated by `vertex`. Bands already
/// meeting the corner lose their caps against the spherical patch.
///
/// Where no single ball touches all the planar hosts, the corner is the
/// exact envelope of the feasible balls: spheres at the offset region's
/// vertices and cylinders along its ridges. A curved trihedral corner uses
/// the ball seated on its three host surfaces.
///
/// Nodes shared with other shapes are copied before the operation.
///
/// # Errors
///
/// Returns a construction error for a nonpositive radius, a nonconvex
/// corner, or hosts that cannot seat a ball. A curved corner requires
/// three distinct host surfaces. An unclosed tool or cut is refused.
pub fn round_vertex(
    model: &mut Model,
    solid: &Shape,
    vertex: &Shape,
    radius: f64,
    tol: Tolerances,
) -> OgeomResult<Built> {
    ogeom_algo::on_own_nodes(
        model,
        solid,
        std::slice::from_ref(vertex),
        |model, solid, parts| round_own(model, solid, &parts[0], radius, tol),
    )
}

fn round_own(
    model: &mut Model,
    solid: &Shape,
    vertex: &Shape,
    radius: f64,
    tol: Tolerances,
) -> OgeomResult<Built> {
    let mut built = match corner_at(model, solid, vertex, radius, tol)? {
        Corner::OneBall(one) => one_ball(model, solid, &one, radius, tol),
        Corner::Setback(corner, normals) => {
            super::vertex_envelope::round(model, solid, vertex, corner, &normals, radius, tol)
        }
        Corner::Curved(corner) => {
            super::vertex_curved::round(model, solid, vertex, corner, radius, tol)
        }
    }?;
    super::guards::solid_fits(model, &built.shape, tol)?;
    let inherited: Vec<Shape> = ogeom_topo::explore_unique(model, solid, ShapeType::Face)?
        .iter()
        .flat_map(|face| built.history.trace(face).to_vec())
        .collect();
    for face in ogeom_topo::explore_unique(model, &built.shape, ShapeType::Face)? {
        if !inherited.iter().any(|image| image.is_same(&face)) {
            built.history.generate(vertex, face);
        }
    }
    built.history.modify(vertex, built.shape.clone());
    Ok(built)
}

fn one_ball(
    model: &mut Model,
    solid: &Shape,
    one: &OneBall,
    radius: f64,
    tol: Tolerances,
) -> OgeomResult<Built> {
    let mut carried = Built::from_nothing(solid.clone());
    for k in 0..one.d.len() {
        let planes = [
            one.m[one.ring[k]],
            one.m[one.ring[(k + 1) % one.ring.len()]],
        ];
        if let Some(band) = super::vertex_carry::carry(
            model,
            &carried.shape,
            one.corner,
            one.far,
            &one.d,
            k,
            planes,
            radius,
            true,
            tol,
        )? {
            carried = Built {
                shape: band.shape,
                history: carried.history.then(&band.history),
            };
        }
    }
    let mut walls: Vec<_> = one.m.iter().map(|m| (*m, one.corner)).collect();
    walls.extend(one.d.iter().map(|d| (-d.vector(), one.far)));
    let tool = super::vertex_tools::ball_polytope(model, &walls, one.far, radius, tol)?;
    let cut = ogeom_bool::cut(model, &carried.shape, &tool, tol)?;
    Ok(Built {
        shape: cut.shape,
        history: carried.history.then(&cut.history),
    })
}
